"""Restore actual v1 journal bytes generated by committed baseline 167ac7e."""
from pathlib import Path

_FIXTURES = Path(__file__).parent / "fixtures" / "f5-recovery-167ac7e"


def restore_saved_f5_journal(coordinator, name):
    coordinator.journal.path.parent.mkdir(parents=True, exist_ok=True)
    coordinator.journal.path.write_bytes((_FIXTURES / (name + ".journal.json")).read_bytes())
